'use strict';
(function(){
  const C=window.Curriculum,B=window.PhysicsBank,app=document.getElementById('app');
  let language='ta',saved=[],lastLesson='02/projectile',filter='all',search='',storageOK=true;
  function read(key,fallback){try{const value=JSON.parse(localStorage.getItem(key));return value??fallback}catch{storageOK=false;return fallback}}
  function write(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{storageOK=false}}
  language=read('iyal-language','ta')==='en'?'en':'ta';
  const loaded=read('iyal-saved',[]);saved=Array.isArray(loaded)?loaded.filter(id=>typeof id==='string'&&C.chapters.some(c=>c.lessons.some(l=>l.id===id))):[];
  const recent=read('iyal-last-lesson','02/projectile');if(typeof recent==='string'&&C.getLesson(...recent.split('/')))lastLesson=recent;
  const T=(en,ta)=>language==='ta'?ta:en, label=o=>o[language];
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icons={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',chapters:'M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z',practice:'M8 3h8v4H8zM6 5H4v16h16V5h-2M8 12h8M8 16h5',progress:'M4 20V4M4 20h17M8 16v-4M13 16V8M18 16V5',arrow:'M5 12h14M13 6l6 6-6 6',bookmark:'M6 3h12v18l-6-4-6 4Z',check:'m5 12 4 4L19 6',back:'m14 6-6 6 6 6',search:'M16 16l5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',play:'m8 4 12 8-12 8Z'};
  const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.chapters}"/></svg>`;
  const href=(id,slug)=>'#/chapter/'+id+(slug?'/'+slug:'');
  function data(){const history=B.clean(read('iyal-practice-v1',[]));return{history,score:B.evaluate(history),attempts:history.filter(a=>!a.viewed)}}
  function parse(hash=location.hash){const p=hash.replace(/^#\/?/,'').split('/');if(!p[0]||p[0]==='home')return{type:'home'};if(['chapters','practice','progress'].includes(p[0])&&p.length===1)return{type:p[0]};if(p[0]==='chapter'&&C.getChapter(p[1])){if(p.length===2)return{type:'chapter',chapter:C.getChapter(p[1])};if(p.length===3&&C.getLesson(p[1],p[2]))return{type:'lesson',chapter:C.getChapter(p[1]),lesson:C.getLesson(p[1],p[2])}}return{type:'missing'}}
  function nav(active){return[['home','Home','முகப்பு'],['chapters','Explore chapters','பாடங்கள்'],['practice','Practice studio','பயிற்சி'],['progress','My progress','முன்னேற்றம்']].map(([id,en,ta])=>`<a href="#/${id}" class="nav-link ${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(id)}<span>${T(en,ta)}</span>${id==='chapters'?'<small>11</small>':''}</a>`).join('')}
  function layout(route,content){const active=['chapter','lesson'].includes(route.type)?'chapters':route.type;return `<aside class="sidebar"><a class="wordmark" href="#/home"><span class="brand-symbol">இ</span><span>இயல்<small>PHYSICS, EXPLORED.</small></span></a><div class="nav-caption">${T('YOUR SPACE','உங்கள் கற்றல் வெளி')}</div><nav aria-label="${T('Main navigation','முதன்மை வழிசெலுத்தல்')}">${nav(active)}</nav><div class="sidebar-bottom"><div class="mini-course"><span>A/L</span><div>${T('Physics','பௌதிகவியல்')}<small>${T('Sri Lankan curriculum','இலங்கைப் பாடத்திட்டம்')}</small></div></div><p>${T('A little curiosity goes a long way.','சிறு ஆர்வம். ஆழமான புரிதல்.')}</p><a href="${C.course}" target="_blank" rel="noopener">e-thaksalawa ↗</a></div></aside><div class="app-body"><header class="topbar"><span class="top-crumb">${T('Your learning space','உங்கள் கற்றல் பயணம்')} <span>/</span> ${T('A/L Physics','உயர்தரப் பௌதிகவியல்')}</span><div class="top-actions"><span class="beta">${T('EARLY ACCESS','முன்மாதிரி')}</span><button id="switch-language" aria-label="${T('Switch to Tamil','Switch to English')}">${T('தமிழ்','English')} <span>⇄</span></button><span class="avatar" aria-hidden="true">இ</span></div></header><main id="main" tabindex="-1">${content}</main><footer class="app-footer"><span>இயல் <span>·</span> ${T('Learn by figuring it out.','ஆராய்ந்து கற்றுக்கொள்ளுங்கள்.')}</span><span>${storageOK?T('Your progress stays in this browser.','முன்னேற்றம் இந்த உலாவியில் சேமிக்கப்படும்.'):T('Storage unavailable; session only.','சேமிப்பு கிடைக்கவில்லை; இவ்வமர்வு மட்டும்.')}</span></footer></div>`}
  function heading(kicker,title,desc,action=''){return `<div class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1>${desc?`<p class="page-desc">${desc}</p>`:''}</div>${action}</div>`}
  function btn(url,text,style='btn-blue'){return `<a class="btn ${style}" href="${url}">${text}${icon('arrow',18)}</a>`}
  function status(l,score){return l.available?(score.ready?T('Review ready','மீளாய்வுக்குத் தயார்'):score.total?T('In progress','பயிற்சியில்'):T('Try the lab','முயன்று பாருங்கள்')):T('Outline ready','பாட வரைவு')}
  function card(c,s){const assessed=c.id==='02'&&s.total>0;return `<a class="chapter-card" style="--chapter:${c.color}" href="${href(c.id)}"><div class="card-top"><span class="chapter-number">${c.id}</span><span class="formula-mark">${esc(c.formula)}</span></div><h3>${esc(label(c))}</h3><p>${esc(c.description[language])}</p><div class="card-footer"><span>${c.lessons.length} ${T('subchapters','உட்பாடங்கள்')}</span><span class="card-arrow">${icon('arrow',17)}</span></div>${assessed?`<div class="card-evidence">${T('Projectile practice in progress','எறிய இயக்கப் பயிற்சி தொடங்கியுள்ளது')}</div>`:''}</a>`}
  function trajectory(){return `<svg class="trajectory" viewBox="0 0 400 180" role="img" aria-label="${T('Illustrative projectile path with horizontal and vertical components','கிடை மற்றும் நிலைக்குத்துக் கூறுகளுடன் எறியப் பாதை')}"><defs><pattern id="grid" width="35" height="35" patternUnits="userSpaceOnUse"><path d="M35 0H0V35" fill="none" stroke="#ffffff" stroke-opacity=".1"/></pattern></defs><rect width="400" height="180" fill="url(#grid)"/><path d="M24 151Q194 -88 367 151" fill="none" stroke="#d5fb69" stroke-width="3" stroke-dasharray="5 7"/><path d="M24 151H377" stroke="#ffffff" stroke-opacity=".4"/><circle cx="196" cy="31" r="7" fill="#d5fb69"/><path d="M196 31h69m-8-6 8 6-8 6" fill="none" stroke="white" stroke-width="2"/><text x="270" y="36" fill="white" font-size="15">vₓ</text><text x="177" y="64" fill="#d5fb69" font-size="14">vᵧ = 0</text><text x="35" y="173" fill="#c3ccff" font-size="12">x →</text></svg>`}
  function activity(attempts){const days=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const start=new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime(),end=start+86400000,count=attempts.filter(a=>a.at>=start&&a.at<end).length;days.push({day:d.getDate().toString(),count,today:i===0})}const max=Math.max(4,...days.map(d=>d.count));return `<div class="activity-chart" role="img" aria-label="${esc(days.map(d=>d.day+': '+d.count).join(', '))}">${days.map(d=>`<div class="day"><span>${d.count||'·'}</span><div class="bar-slot"><i style="height:${Math.max(4,d.count/max*100)}%;opacity:${d.count?1:.16}" class="${d.today?'today':''}"></i></div><small>${esc(d.day)}</small></div>`).join('')}</div>`}
  function home(d){const {score:s,attempts}=d,lesson=C.getLesson(...lastLesson.split('/'));return heading(T('MAKE ROOM FOR DISCOVERY','இன்று புதிதாகக் கண்டறிவோம்'),T('Small steps. Big understanding.','சிறு முயற்சி. ஆழமான புரிதல்.'),T('Your physics journey, one idea at a time.','உங்கள் பௌதிகவியல் பயணம், ஒவ்வொரு கருத்தாக.'),btn('#/chapters',T('Explore chapters','பாடங்களை ஆராய்க'),'btn-dark'))+`<div class="home-grid"><section class="continue-card"><div class="continue-copy"><span class="pill">${T('YOUR NEXT EXPERIMENT','உங்கள் அடுத்த பரிசோதனை')}</span><p class="tiny-label">02 / ${T('MECHANICS','பொறியியல்')}</p><h2>${T('Make the leap.','எறிந்து பாருங்கள்.')}</h2><p>${T('Change the angle. Follow the motion. Find out why.','கோணத்தை மாற்றுங்கள். இயக்கத்தைக் கவனியுங்கள். காரணத்தைக் கண்டறியுங்கள்.')}</p>${btn(href('02','projectile'),s.total?T('Continue learning','கற்றலைத் தொடர்க'):T('Open projectile lab','எறிய இயக்க ஆய்வகம்'),'btn-lime')}</div><div class="continue-visual">${trajectory()}<span class="visual-caption">${T('PROJECTILE MOTION · INTERACTIVE LAB','எறிய இயக்கம் · ஊடாடும் ஆய்வகம்')}</span></div></section><section class="activity-card"><div class="section-title"><h2>${T('Your week','இந்த வாரம்')}</h2><span class="subtle">${T('7 days','7 நாட்கள்')}</span></div>${activity(attempts)}<p>${T('Questions answered each day. Every attempt counts as activity.','ஒவ்வொரு நாளும் விடையளித்த வினாக்கள். ஒவ்வொரு முயற்சியும் செயல்பாடாகும்.')}</p></section></div><div class="stats-row"><div class="stat"><span class="stat-icon blue">${icon('practice')}</span><div><strong>${attempts.length}</strong><span>${T('Answers checked','சரிபார்த்த விடைகள்')}</span></div></div><div class="stat"><span class="stat-icon purple">${icon('progress')}</span><div><strong>${s.total?s.accuracy+'%':'—'}</strong><span>${T('Independent practice accuracy','உதவியற்ற பயிற்சித் துல்லியம்')}</span></div></div><div class="stat"><span class="stat-icon green">${icon('chapters')}</span><div><strong>${s.total?1:0}<small> / ${C.total}</small></strong><span>${T('Subchapters assessed','மதிப்பிட்ட உட்பாடங்கள்')}</span></div></div></div><div class="lower-home"><section><div class="section-title"><h2>${T('A whole world to explore','ஆராயக் காத்திருக்கும் உலகம்')}</h2><a class="text-link" href="#/chapters">${T('All 11 chapters','11 பாடங்களும்')} ↗</a></div><div class="home-chapters">${C.chapters.slice(0,3).map(c=>card(c,s)).join('')}</div></section><section class="focus-card"><span class="eyebrow">${T('YOUR NEXT MOVE','அடுத்த படி')}</span><h2>${s.ready?T('Make space for another topic.','வேறு தலைப்புக்கும் நேரம் ஒதுக்கலாம்.'):T('Understanding before speed.','வேகத்திற்கு முன் புரிதல்.')}</h2><p>${s.ready?T('Your projectile evidence meets the prototype threshold. Keep a short review and explore an unassessed area next.','எறிய இயக்கத்தில் முன்மாதிரி அளவுகோலை அடைந்துள்ளீர்கள். சிறு மீளாய்வுடன் மதிப்பிடப்படாத பகுதியையும் ஆராயுங்கள்.'):T('Try different question styles. Your study plan will adapt to the evidence you build.','பல வகை வினாக்களை முயலுங்கள். உங்கள் பெறுபேறுகளுக்கேற்ப கற்றல் திட்டம் மாறும்.')}</p>${btn('#/progress',T('See my progress','முன்னேற்றத்தைப் பார்க்க'),'btn-white')}<div class="focus-note">${T('Currently assessing projectile motion only.','தற்போது எறிய இயக்கம் மட்டும் மதிப்பிடப்படுகிறது.')}</div></section></div>${lesson&&!lesson.available?`<div class="last-outline">${T('Last explored','கடைசியாக ஆராய்ந்தது')}: <a href="${href(...lastLesson.split('/'))}">${esc(label(lesson))} ↗</a></div>`:''}`}
  function explorer(d){return heading(T('THE CHAPTER EXPLORER','பாடங்களை ஆராய்க'),T('Follow your curiosity.','உங்கள் ஆர்வத்தைத் தொடருங்கள்.'),T(`11 chapters. ${C.total} subchapter workspaces. Start anywhere.`,`11 பாடங்கள். ${C.total} உட்பாடப் பக்கங்கள். எங்கிருந்தும் தொடங்குங்கள்.`))+`<div class="explore-tools"><label class="search-field">${icon('search')}<input id="chapter-search" type="search" value="${esc(search)}" placeholder="${T('Find a chapter or concept…','பாடம் அல்லது கருத்தைத் தேடுக…')}" aria-label="${T('Search chapters and subchapters','பாடங்களையும் உட்பாடங்களையும் தேடுக')}"></label><div class="filters">${[['all','All chapters','அனைத்தும்'],['available','With a live lab','ஆய்வகம் உள்ளது'],['saved','Saved','சேமித்தவை']].map(([id,en,ta])=>`<button data-filter="${id}" aria-pressed="${filter===id}" class="${filter===id?'selected':''}">${T(en,ta)}</button>`).join('')}</div></div><p class="outline-note">${T('Chapter order follows e-thaksalawa. Subtopics are grouped for this app and await educator review. One interactive lesson is available; the remaining pages are outlines.','பாட வரிசை e-thaksalawa அடிப்படையிலானது. உட்பாடங்கள் இச்செயலிக்காகத் தொகுக்கப்பட்டுள்ளன; ஆசிரியர் மீளாய்வு நிலுவையில். ஓர் ஊடாடும் பாடம் உள்ளது; மற்றவை பாட வரைவுகள்.')}</p><div id="chapter-results">${explorerResults(d)}</div>`}
  function explorerResults(d){const query=search.trim().toLocaleLowerCase(),matches=C.chapters.filter(c=>(filter!=='available'||c.lessons.some(l=>l.available))&&(filter!=='saved'||c.lessons.some(l=>saved.includes(l.id)))&&(!query||[c.en,c.ta,...c.lessons.flatMap(l=>[l.en,l.ta])].some(s=>s.toLocaleLowerCase().includes(query))));return `<p class="results-count" role="status">${matches.length} ${T('chapters','பாடங்கள்')}</p><div class="chapter-grid">${matches.map(c=>card(c,d.score)).join('')}</div>${!matches.length?`<div class="empty-state"><h2>${T('No chapters found','பாடங்கள் கிடைக்கவில்லை')}</h2><p>${T('Try another search or select All chapters. Save a subchapter from its page to find it here.','வேறு சொல்லைத் தேடவும் அல்லது அனைத்தையும் தேர்க. உட்பாடப் பக்கத்தில் சேமித்தவை இங்கு தோன்றும்.')}</p></div>`:''}`}
  function chapter(c,d){const assessed=c.id==='02'&&d.score.total>0;return `<a class="breadcrumb" href="#/chapters">${icon('back',16)}${T('All chapters','அனைத்துப் பாடங்களும்')}</a><section class="chapter-hero" style="--chapter:${c.color}"><div><p class="eyebrow">${T('CHAPTER','பாடம்')} ${c.id} <span>·</span> ${c.lessons.length} ${T('SUBCHAPTERS','உட்பாடங்கள்')}</p><h1>${esc(label(c))}</h1><p>${esc(c.description[language])}</p></div><div class="chapter-equation" aria-hidden="true">${esc(c.formula)}</div></section><div class="chapter-layout"><section class="lesson-list"><div class="section-title"><h2>${T('Your learning path','உங்கள் கற்றல் பாதை')}</h2><span class="subtle">${T('Explore at your pace','உங்கள் வேகத்தில் கற்றிடுங்கள்')}</span></div>${c.lessons.map(l=>`<a class="lesson-row" href="${href(c.id,l.slug)}"><span class="lesson-step ${l.available?'live':''}">${l.available?icon('play',19):String(l.index).padStart(2,'0')}</span><div><h3>${esc(label(l))}</h3><p>${l.available?T('Experiment + practice + self-evaluation','பரிசோதனை + பயிற்சி + சுய மதிப்பீடு'):T('Theory · experiment · practice workspace','கோட்பாடு · பரிசோதனை · பயிற்சிக்கான பக்கம்')}</p></div><span class="lesson-status ${l.available?'live-label':''}">${status(l,d.score)}</span>${saved.includes(l.id)?icon('bookmark',17):icon('arrow',18)}</a>`).join('')}</section><aside class="chapter-aside"><h2>${T('Chapter snapshot','பாடத்தின் நிலை')}</h2><div class="mini-stat"><strong>${assessed?1:0}<small> / ${c.lessons.length}</small></strong><span>${T('subchapters assessed','மதிப்பிட்ட உட்பாடங்கள்')}</span></div><progress max="${c.lessons.length}" value="${assessed?1:0}" aria-label="${T('Assessment coverage','மதிப்பீட்டுப் பரவல்')}"></progress><p>${T('Opening a page does not mark a lesson complete. Progress is based on practice evidence.','பக்கத்தைத் திறப்பதால் பாடம் முடிந்ததாகக் கருதப்படாது. பயிற்சி முடிவுகளே முன்னேற்றத்தின் அடிப்படை.')}</p><div class="aside-divider"></div><h3>${T('From the curriculum','பாடத்திட்டத் தொடர்பு')}</h3><p>${T('Explore the reference resources while we build the lesson experiences.','ஊடாடும் பாடங்களை உருவாக்கும் வரை மூல வளங்களை ஆராயலாம்.')}</p><a class="text-link" href="${c.source}" target="_blank" rel="noopener">e-thaksalawa ↗</a><span class="aside-note">${T('Lesson grouping: draft for educator review.','உட்பாடத் தொகுப்பு: ஆசிரியர் மீளாய்வுக்கான வரைவு.')}</span></aside></div>`}
  function lesson(c,l,d){const active=l.available;return `<a class="breadcrumb" href="${href(c.id)}">${icon('back',16)}${esc(label(c))}</a><div class="lesson-heading"><div><p class="eyebrow">${T('CHAPTER','பாடம்')} ${c.id} / ${String(l.index).padStart(2,'0')}</p><h1>${esc(label(l))}</h1><span class="pill ${active?'pill-live':'pill-outline'}">${status(l,d.score)}</span></div><button id="save-lesson" class="save-button ${saved.includes(l.id)?'is-saved':''}" aria-pressed="${saved.includes(l.id)}">${icon('bookmark',18)}${saved.includes(l.id)?T('Saved','சேமிக்கப்பட்டது'):T('Save for later','பிறகு கற்கச் சேமிக்க')}</button></div>${active?`<div class="lesson-ready-note">${T('Experiment, connect the equations, then put your understanding to the test.','பரிசோதனை செய்து, சமன்பாடுகளுடன் தொடர்புபடுத்தி, உங்கள் புரிதலைச் சோதியுங்கள்.')}</div><iframe id="lesson-frame" title="${T('Projectile motion interactive lesson','எறிய இயக்க ஊடாடும் பாடம்')}" src="lab.html?embed=1&lang=${language}" class="lesson-frame"></iframe>`:outline(c,l)}<div class="lesson-pagination">${l.index>1?btn(href(c.id,c.lessons[l.index-2].slug),T('Previous subchapter','முந்தைய உட்பாடம்'),'btn-white'):'<span></span>'}${l.index<c.lessons.length?btn(href(c.id,c.lessons[l.index].slug),T('Next subchapter','அடுத்த உட்பாடம்'),'btn-white'):btn('#/chapters',T('Explore another chapter','வேறு பாடத்தை ஆராய்க'),'btn-white')}</div>`}
  function outline(c,l){return `<section class="outline-workspace"><div class="outline-tabs" role="tablist" aria-label="${T('Lesson sections','பாடப் பகுதிகள்')}">${[['learn','Understand','புரிதல்'],['experiment','Experiment','பரிசோதனை'],['practice','Practise','பயிற்சி'],['evaluate','Evaluate','மதிப்பீடு']].map(([id,en,ta],i)=>`<button role="tab" id="tab-${id}" aria-controls="outline-panel" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-stage="${id}"><span>0${i+1}</span>${T(en,ta)}</button>`).join('')}</div><div id="outline-panel" role="tabpanel" aria-labelledby="tab-learn" tabindex="0">${stageContent('learn',l)}</div></section><div class="outline-resources"><div><h3>${T('Keep exploring while this lesson takes shape.','இப்பாடம் உருவாகும் வரை தொடர்ந்து ஆராயுங்கள்.')}</h3><p>${T('Open the reference course, or try the completed projectile experience.','மூலப் பாடத்தைத் திறக்கவும் அல்லது உருவாக்கப்பட்ட எறிய இயக்கப் பாடத்தை முயலவும்.')}</p></div><a class="btn btn-white" href="${c.source}" target="_blank" rel="noopener">e-thaksalawa ↗</a>${btn(href('02','projectile'),T('Try the working lesson','ஊடாடும் பாடத்தை முயல்க'),'btn-blue')}</div>`}
  function stageContent(stage,l){const copy={learn:[T('Build the idea.','கருத்தைப் புரிந்துகொள்ளுங்கள்.'),T('This space will connect explanations, diagrams and key equations for','இங்கு விளக்கங்கள், வரைபுகள், முக்கிய சமன்பாடுகளுடன் கற்கவிருப்பது'),T('Concept explanation','கருத்து விளக்கம்'),T('Key equations & examples','முக்கிய சமன்பாடுகளும் உதாரணங்களும்')],experiment:[T('Change something. See what happens.','மாற்றிப் பாருங்கள். விளைவைக் கவனியுங்கள்.'),T('A guided interactive experiment is planned for','வழிகாட்டப்பட்ட ஊடாடும் பரிசோதனை உருவாகவிருப்பது'),T('Predict & adjust variables','ஊகித்தல் மற்றும் மாறிகளை மாற்றுதல்'),T('Observe & explain','அவதானித்தல் மற்றும் விளக்குதல்')],practice:[T('Try the idea in a new question.','புதிய வினாவில் கருத்தைப் பயன்படுத்துங்கள்.'),T('Worked practice and sourced past-paper connections are planned for','விளக்கங்களுடனான பயிற்சியும் மூல வினாத்தாள் தொடர்புகளும் உருவாகவிருப்பது'),T('Past-paper connections','கடந்த வினாத்தாள் தொடர்புகள்'),T('Varied practice questions','பல்வகைப் பயிற்சி வினாக்கள்')],evaluate:[T('Find out what has clicked.','உங்கள் புரிதலை அறியுங்கள்.'),T('Independent questions will provide evidence of understanding in','உதவியற்ற வினாக்கள் மூலம் புரிதல் மதிப்பிடப்படவிருப்பது'),T('Different question styles','வேறுபட்ட வினா வகைகள்'),T('Personal study recommendation','தனிப்பட்ட கற்றல் பரிந்துரை')]};const a=copy[stage];return `<span class="outline-stamp">${T('LESSON IN DEVELOPMENT','பாடம் உருவாக்கத்தில்')}</span><h2>${a[0]}</h2><p>${a[1]} <strong>${esc(label(l))}</strong>.</p><div class="planned-items"><span>○ ${a[2]}</span><span>○ ${a[3]}</span></div><p class="not-assessed">${T('This is a lesson workspace, not a completed lesson. No completion or mastery is awarded here yet.','இது பாடத்திற்கான பக்கம்; முழுமையான பாடம் இன்னும் இல்லை. இங்கு பாட நிறைவு அல்லது தேர்ச்சி வழங்கப்படாது.')}</p>`}
  function practice(d){return heading(T('PRACTICE STUDIO','பயிற்சிக் கூடம்'),T('Make understanding stick.','புரிதலை உறுதிப்படுத்துங்கள்.'),T('Past-paper connections. Fresh questions. Feedback that points you forward.','கடந்த வினாத்தாள் தொடர்புகள். புதிய வினாக்கள். அடுத்த படிக்கான பின்னூட்டம்.'))+`<div class="practice-course-strip"><span class="chapter-number">02</span><div><strong>${T('Projectile motion','எறிய இயக்கம்')}</strong><span>${T('64 questions · 18 styles · 6 skills','64 வினாக்கள் · 18 வகைகள் · 6 திறன்கள்')}</span></div><a class="text-link" href="${href('02','projectile')}">${T('Open lesson','பாடத்தைத் திறக்க')} ↗</a></div><iframe id="lesson-frame" title="${T('Practice bank and self-evaluation','பயிற்சி வினாவங்கியும் சுய மதிப்பீடும்')}" class="lesson-frame" src="lab.html?embed=1&view=practice&lang=${language}"></iframe>`}
  function progress(d){const s=d.score,secure=s.skills.filter(k=>k.secure).length;return heading(T('YOUR LEARNING, MADE VISIBLE','உங்கள் கற்றலைக் காணுங்கள்'),T('Progress you can build on.','தொடர்ந்து வளர்க்கும் முன்னேற்றம்.'),T('Based on your answers, not the pages you open.','திறந்த பக்கங்களில் அல்ல; உங்கள் விடைகளில் அடிப்படையான முன்னேற்றம்.'))+`<div class="progress-top"><section class="progress-summary"><div class="progress-ring" style="--fill:${secure/6*100}%"><strong>${secure}<span>/ 6</span></strong></div><div><span class="eyebrow">${T('PROJECTILE MOTION','எறிய இயக்கம்')}</span><h2>${s.ready?T('Ready for a new focus.','புதிய பகுதிக்கு நேரம் ஒதுக்கலாம்.'):T('Every skill needs evidence.','ஒவ்வொரு திறனுக்கும் சான்று தேவை.')}</h2><p>${s.total?T(`${s.total} question styles assessed · ${s.accuracy}% independent accuracy`,`${s.total} வினா வகைகள் மதிப்பிடப்பட்டன · ${s.accuracy}% உதவியற்ற துல்லியம்`):T('Answer a few independent questions to establish your starting point.','உங்கள் தற்போதைய நிலையை அறிய சில உதவியற்ற வினாக்களுக்கு விடையளிக்கவும்.')}</p>${btn('#/practice',T('Continue practice','பயிற்சியைத் தொடர்க'),'btn-blue')}</div></section><section class="progress-advice"><span class="eyebrow">${T('NEXT STEP','அடுத்த படி')}</span><h2>${s.reviewDue?T('A short review is due.','சிறு மீளாய்வு தேவை.'):s.ready?T('Explore an unassessed topic.','மதிப்பிடப்படாத தலைப்பை ஆராயுங்கள்.'):T('Build breadth, then confidence.','பல வகைகளில் பயிற்சி செய்யுங்கள்.')}</h2><p>${s.ready?T('Your projectile results meet our prototype threshold. Review in 2 days and explore another area. Other chapters are not yet assessed.','எறிய இயக்கத்தில் முன்மாதிரி அளவுகோலை அடைந்துள்ளீர்கள். 2 நாட்களில் மீளாய்வு செய்து வேறு பகுதியை ஆராயுங்கள். மற்ற பாடங்கள் இன்னும் மதிப்பிடப்படவில்லை.'):T('Aim for 12 distinct styles, 85% accuracy, and 2 correct styles in every skill. Viewed solutions and exact repeats cannot raise readiness.','12 வகைகள், 85% துல்லியம், ஒவ்வொரு திறனிலும் 2 சரியான வகைகள் என்பதே இலக்கு. பார்த்த விளக்கங்களும் அதே வினாவின் மீள்முயற்சிகளும் தயார்நிலையை உயர்த்தாது.')}</p><small>${T('Prototype guidance, not a predicted exam grade.','முன்மாதிரி வழிகாட்டல்; பரீட்சைப் பெறுபேறு முன்னறிவிப்பு அல்ல.')}</small></section></div><div class="section-title"><h2>${T('Your skill map','உங்கள் திறன் வரைபடம்')}</h2><span class="subtle">${T('Projectile motion only','எறிய இயக்கம் மட்டும்')}</span></div><div class="skill-grid">${s.skills.map(k=>`<div class="skill-card"><span class="skill-symbol ${k.secure?'secured':''}">${k.secure?icon('check'):icon('progress')}</span><h3>${esc(label(B.families[k.id]))}</h3><strong>${k.total?k.correct+'/'+k.total:'—'}</strong><span>${k.total?T('independent styles correct','உதவியின்றிச் சரியான வகைகள்'):T('Not assessed yet','இன்னும் மதிப்பிடப்படவில்லை')}</span><progress max="2" value="${Math.min(k.correct,2)}" aria-label="${esc(label(B.families[k.id]))}"></progress></div>`).join('')}</div><div class="section-title spaced"><h2>${T('Across the curriculum','பாடத்திட்டம் முழுவதும்')}</h2><a href="#/chapters" class="text-link">${T('Explore chapters','பாடங்களை ஆராய்க')} ↗</a></div><div class="curriculum-progress">${C.chapters.map(c=>`<a href="${href(c.id)}"><span style="color:${c.color}">${c.id}</span><strong>${esc(label(c))}</strong><span>${c.id==='02'&&s.total?T('1 subchapter assessed','1 உட்பாடம் மதிப்பிடப்பட்டது'):T('Not assessed','மதிப்பிடப்படவில்லை')}</span>${icon('arrow',17)}</a>`).join('')}</div>`}
  function bind(route){document.getElementById('skip-to-content').onclick=e=>{e.preventDefault();document.getElementById('main').focus()};document.getElementById('switch-language').onclick=()=>{language=language==='ta'?'en':'ta';write('iyal-language',language);render(false)};
    const searchEl=document.getElementById('chapter-search');if(searchEl)searchEl.addEventListener('input',()=>{search=searchEl.value;document.getElementById('chapter-results').innerHTML=explorerResults(data())});
    document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render(false)});
    const save=document.getElementById('save-lesson');if(save)save.onclick=()=>{const id=route.lesson.id;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];write('iyal-saved',saved);save.classList.toggle('is-saved',saved.includes(id));save.setAttribute('aria-pressed',String(saved.includes(id)));save.innerHTML=icon('bookmark',18)+(saved.includes(id)?T('Saved','சேமிக்கப்பட்டது'):T('Save for later','பிறகு கற்கச் சேமிக்க'))};
    const tabs=[...document.querySelectorAll('[data-stage]')];function choose(b){tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===b));t.tabIndex=t===b?0:-1});document.getElementById('outline-panel').innerHTML=stageContent(b.dataset.stage,route.lesson);document.getElementById('outline-panel').setAttribute('aria-labelledby',b.id)}tabs.forEach((b,i)=>{b.onclick=()=>choose(b);b.onkeydown=e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;choose(tabs[n]);tabs[n].focus()}}});
  }
  function render(scroll=true){const route=parse(),d=data();if(route.type==='lesson'){lastLesson=route.lesson.id;write('iyal-last-lesson',lastLesson)}let content;switch(route.type){case'home':content=home(d);break;case'chapters':content=explorer(d);break;case'chapter':content=chapter(route.chapter,d);break;case'lesson':content=lesson(route.chapter,route.lesson,d);break;case'practice':content=practice(d);break;case'progress':content=progress(d);break;default:content=heading('404',T('This page wandered off.','இப்பக்கம் கிடைக்கவில்லை.'),T('Choose a chapter to get back on track.','தொடர்ந்து கற்க ஒரு பாடத்தைத் தேர்க.'),btn('#/chapters',T('Explore chapters','பாடங்களை ஆராய்க')))}app.innerHTML=layout(route,content);document.documentElement.lang=language;document.title=(route.lesson?label(route.lesson):route.chapter?label(route.chapter):T('Your physics journey','உங்கள் பௌதிகவியல் பயணம்'))+' · இயல்';bind(route);if(scroll){window.scrollTo(0,0);document.getElementById('main').focus({preventScroll:true})}}
  window.addEventListener('hashchange',()=>render());window.addEventListener('storage',e=>{if(e.key==='iyal-practice-v1'&&['home','progress'].includes(parse().type))render(false)});
  window.addEventListener('message',e=>{const frame=document.getElementById('lesson-frame');if(e.origin!==location.origin||e.source!==frame?.contentWindow)return;if(e.data?.type==='iyal-height'&&Number.isFinite(e.data.height)){frame.style.height=Math.max(400,Math.min(18000,e.data.height))+'px'}});
  window.IyalApp={parse,render};render(false);
})();
